/**
 * Writes the generated files from the registry: `generated/methods.generated.ts` (plain string tables, no zod, so preload
 * can import it) and `generated/openapi.json` (OpenAPI 3.1 through `z.toJSONSchema`). Run `npm run generate -w @aplos/contract`;
 * `tests/generated.test.ts` fails when either file is stale.
 */
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { format, resolveConfig } from 'prettier';
import * as z from 'zod/mini';
import * as contract from '../src/index';
import { apiVersion, Bytes, getMethod, methodNames, scopes, type MethodDef } from '../src/index';

const root = join(import.meta.dirname, '..');
const sorted = (names: Iterable<string>) => [...names].sort();
const list = (name: string, names: string[], doc: string) =>
  `/** ${doc} */\nexport const ${name} = [\n${names.map(n => `  '${n}',`).join('\n')}\n] as const;\n`;
const record = (name: string, type: string, entries: [string, string][], doc: string) =>
  `/** ${doc} */\nexport const ${name}: Record<string, ${type}> = {\n${entries.map(([k, v]) => `  '${k}': '${v}',`).join('\n')}\n};\n`;

const defs = methodNames.map(name => [name, getMethod(name)] as [string, MethodDef]);
const pick = (test: (def: MethodDef) => boolean) =>
  sorted(defs.filter(([, def]) => test(def)).map(([name]) => name));
/** What the socket and loopback HTTP listener may carry: engine methods that are not UI-only, secret or for main alone. */
const listenable = (def: MethodDef) =>
  def.host === 'engine' && !def.uiOnly && !def.secret && def.scope !== 'host';
/** What the MCP adapter exposes: listenable `read` and `draft` methods that are not audited, so nothing destructive (Draft/destroy) runs unprompted. */
const mcpExposed = (def: MethodDef) =>
  listenable(def) && (def.scope === 'read' || def.scope === 'draft') && !def.audit;

export function renderMethods(): string {
  const parts = [
    '// Generated by packages/contract/scripts/generate.ts from the registry. Do not edit: run `npm run generate -w @aplos/contract`.',
    '// Plain data with no zod import, so preload can use it. `tests/generated.test.ts` fails when this file is stale.\n',
    `export const apiVersion = ${apiVersion};\n`,
    list(
      'engineMethods',
      pick(d => d.host === 'engine'),
      'Every method the engine serves.',
    ),
    list(
      'desktopMethods',
      pick(d => d.host === 'desktop'),
      "Main's native methods; preload routes these to main, never to the engine.",
    ),
    list(
      'rendererMethods',
      pick(d => d.scope !== 'host'),
      'What preload lets an Electron window call: everything except `host` methods.',
    ),
    list(
      'hostMethods',
      pick(d => d.scope === 'host'),
      "Methods only main's own control connection may call.",
    ),
    list(
      'listenerMethods',
      pick(listenable),
      'What the local socket and loopback HTTP listener may carry (ARCH 12.3).',
    ),
    list(
      'mcpMethods',
      pick(mcpExposed),
      'Methods the MCP adapter exposes as tools: `read` and `draft` scopes, never an audited (destructive) one (ARCH 12.3 item 6).',
    ),
    list(
      'secretMethods',
      pick(d => !!d.secret),
      'Methods whose arguments carry a secret: never logged, never echoed, Electron windows only.',
    ),
    list(
      'uiOnlyMethods',
      pick(d => !!d.uiOnly),
      'Methods only Electron windows (and main) may call, never the socket, HTTP or MCP.',
    ),
    list(
      'auditMethods',
      pick(d => !!d.audit),
      'A call from a non-UI client writes an `audit_log` row.',
    ),
    record(
      'methodHost',
      `'engine' | 'desktop'`,
      defs.map(([n, d]) => [n, d.host]),
      'Host per method.',
    ),
    record(
      'methodScope',
      `'${scopes.join(`' | '`)}'`,
      defs.map(([n, d]) => [n, d.scope]),
      'Listener scope per method.',
    ),
    record(
      'methodKind',
      `'query' | 'command'`,
      defs.map(([n, d]) => [n, d.kind]),
      'Query or command per method.',
    ),
    record(
      'methodArea',
      'string',
      defs.map(([n, d]) => [n, d.area]),
      'Owning area file per method.',
    ),
    record(
      'methodScopeRule',
      `'originating' | 'guests'`,
      defs.flatMap(([n, d]) => (d.scopeRule ? [[n, d.scopeRule]] : [])),
      'The data-dependent scope check a handler adds (`MethodSpec.scopeRule`, freeze FR-3 and FR-4).',
    ),
    `/** Argument paths a listener caller may not set (\`MethodSpec.windowOnlyArgs\`, freeze FR-5). */\nexport const windowOnlyArgs: Record<string, readonly string[]> = {\n${defs.flatMap(([n, d]) => (d.windowOnlyArgs ? [`  '${n}': [${d.windowOnlyArgs.map(a => `'${a}'`).join(', ')}],`] : [])).join('\n')}\n};\n`,
  ];
  return parts.join('\n');
}

/**
 * Every exported schema becomes a named component (`ThreadRow`, `Settings`, `State`...), and every
 * method's input and output one more, so shared types appear once and are `$ref`ed. `io: 'input'` leaves objects open
 * (`additionalProperties` unset): within v1 a newer engine may add fields, and inputs strip unknown keys rather than fail.
 */
function components(): { schemas: Record<string, unknown>; idOf: Map<unknown, string> } {
  const registry = z.registry<{ id: string }>();
  const idOf = new Map<unknown, string>();
  const seen = new Set<unknown>();
  for (const [name, value] of Object.entries(contract).sort(([a], [b]) => a.localeCompare(b))) {
    if (!value || typeof value !== 'object' || !('_zod' in value) || seen.has(value)) continue;
    if (!/^[A-Z]/.test(name)) continue;
    seen.add(value);
    idOf.set(value, name.replace(/Schema$/, ''));
    registry.add(value as z.ZodMiniType, { id: name.replace(/Schema$/, '') });
  }
  for (const [name, def] of defs) {
    if (def.host !== 'engine' || def.scope === 'host') continue;
    for (const [part, schema] of [
      ['input', def.input],
      ['output', def.output],
    ] as const) {
      // A method that reuses a named schema whole (e.g. `Session/get` returns `Session`) refers to it.
      if (!registry.has(schema)) {
        idOf.set(schema, `${name.replace('/', '_')}_${part}`);
        registry.add(schema, { id: idOf.get(schema)! });
      }
    }
  }
  const out = z.toJSONSchema(registry, {
    target: 'draft-2020-12',
    io: 'input',
    uri: id => `#/components/schemas/${id}`,
    unrepresentable: 'any', // Bytes is the only custom type; tests/wire-rules.test.ts fails on any other.
    override: ctx => {
      if (ctx.zodSchema === Bytes) {
        ctx.jsonSchema.type = 'string';
        ctx.jsonSchema.format = 'binary';
      }
    },
  }) as { schemas: Record<string, Record<string, unknown>> };
  for (const schema of Object.values(out.schemas)) {
    delete schema.$schema;
    delete schema.$id;
  }
  return {
    schemas: Object.fromEntries(Object.entries(out.schemas).sort(([a], [b]) => a.localeCompare(b))),
    idOf,
  };
}

export function renderOpenApi(): string {
  const { schemas, idOf } = components();
  const ref = (schema: z.ZodMiniType) => ({ $ref: `#/components/schemas/${idOf.get(schema)}` });
  const paths: Record<string, unknown> = {};
  for (const [name, def] of defs) {
    if (def.host !== 'engine' || def.scope === 'host') continue;
    const id = name.replace('/', '_');
    paths[`/call/${name}`] = {
      post: {
        operationId: id,
        summary: def.summary,
        tags: [def.area],
        'x-aplos-kind': def.kind,
        'x-aplos-scope': def.scope,
        ...(def.audit ? { 'x-aplos-audit': true } : {}),
        ...(!listenable(def) ? { 'x-aplos-ui-only': true } : {}),
        ...(def.scopeRule ? { 'x-aplos-scope-rule': def.scopeRule } : {}),
        ...(def.windowOnlyArgs ? { 'x-aplos-window-only-args': def.windowOnlyArgs } : {}),
        requestBody: {
          required: true,
          content: { 'application/json': { schema: ref(def.input) } },
        },
        responses: {
          200: {
            description: 'The result.',
            content: { 'application/json': { schema: ref(def.output) } },
          },
          default: {
            description: 'A failed call.',
            content: {
              'application/json': { schema: { $ref: '#/components/schemas/ErrorReply' } },
            },
          },
        },
      },
    };
  }
  const doc = {
    openapi: '3.1.0',
    info: {
      title: 'Aplos Mail engine contract',
      version: `${apiVersion}.0.0`,
      description:
        'Contract v1. Additive changes only within v1. Calls are `POST /v1/call/<Type>/<verb>` with the arguments as the body; ' +
        "a command's `opId` is also the `Idempotency-Key`. A failed call answers with `{error}` and a non-2xx status. Frames stream from " +
        '`GET /v1/events` (SSE, `id: <seq>`, `Last-Event-ID` resumes). Blobs are `PUT /v1/blob` and `GET /v1/blob/{id}`. Methods marked ' +
        '`x-aplos-ui-only` are refused by the listener.',
    },
    jsonSchemaDialect: 'https://json-schema.org/draft/2020-12/schema',
    servers: [{ url: 'http://127.0.0.1:{port}/v1', variables: { port: { default: '4317' } } }],
    security: [{ bearer: [] }],
    paths,
    components: {
      securitySchemes: { bearer: { type: 'http', scheme: 'bearer' } },
      schemas: {
        ...schemas,
        ErrorReply: {
          type: 'object',
          properties: { error: { $ref: '#/components/schemas/ErrorBody' } },
          required: ['error'],
        },
      },
    },
  };
  return `${JSON.stringify(doc, null, 2)}\n`;
}

/** Generated files go through the repo's Prettier config, so `format:check` and the golden test agree. */
async function pretty(file: string, text: string): Promise<string> {
  const filepath = join(root, file);
  return format(text, { ...(await resolveConfig(filepath)), filepath });
}

export const generatedFiles: Record<string, () => Promise<string>> = {
  'generated/methods.generated.ts': () => pretty('generated/methods.generated.ts', renderMethods()),
  'generated/openapi.json': () => pretty('generated/openapi.json', renderOpenApi()),
};

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  for (const [file, render] of Object.entries(generatedFiles))
    writeFileSync(join(root, file), await render());
  console.log(
    `Wrote ${Object.keys(generatedFiles).join(' and ')} (${methodNames.length} methods).`,
  );
}
